import json

with open("/root/autodl-tmp/distrib_canary_collapse/artifacts/mmct_results/mmct_results_v2.json") as f:
    data = json.load(f)

# For each mode, count significant per run_id
modes_to_check = ["uniform_forward", "weighted_pair_forward", "weighted_global_forward",
                   "uniform_bidirectional", "weighted_pair_bidirectional", "weighted_global_bidirectional"]

# Alpha sweep
print("=== ALPHA SWEEP PER-RUN ===")
for mode in modes_to_check:
    mode_data = data["results"][mode]
    print(f"\n--- {mode} ---")
    for alpha_key in sorted(mode_data.keys()):
        entries = mode_data[alpha_key]
        # Group by run_id
        by_run = {}
        for e in entries:
            rid = e["run_id"]
            if rid not in by_run:
                by_run[rid] = {"sig": 0, "total": 0}
            by_run[rid]["total"] += 1
            if e["significant"]:
                by_run[rid]["sig"] += 1
        for rid in sorted(by_run.keys()):
            print(f"  {alpha_key}/{rid}: {by_run[rid]['sig']}/{by_run[rid]['total']}")

# Table 7
print("\n=== TABLE 7 PER-CONDITION ===")
t7 = data.get("table7_results", {})
for mode in modes_to_check:
    if mode not in t7:
        continue
    print(f"\n--- {mode} ---")
    for cond, cdata in t7[mode].items():
        print(f"  {cond} ({cdata['model']}, {cdata['data']}): {cdata['n_significant']}/{cdata['n_total']}")
